/**
 * Filesystem writers for the v2 catalog.
 *
 * `writeFlatCatalog` is the canonical writer: one file per catalog root, using
 * the factory-based `renderCatalog` format. The legacy fragment + barrel
 * functions (`writeFragment`, `regenerateBarrel`, `writeCatalog`) are kept for
 * the `import-entity` additive path while it migrates.
 */
import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { CATALOG_META_BY_REF_KIND, catalogBagForRefKind } from "../graph/index.js";
import { renderBarrel, renderCatalog, renderFragment } from "./render.js";
function bagName(kind) {
    const bag = catalogBagForRefKind(kind);
    if (bag === undefined) {
        throw new Error(`catalog bag name unknown for ref kind "${kind}"`);
    }
    return bag;
}
/** Target for an app catalog: `<root>/apps/<appHandle>/generated/catalog.ts`. */
export function appCatalogTarget(root, appHandle, appName) {
    return { dir: join(root, "apps", appHandle, "generated"), handle: appHandle, filename: "catalog", name: appName, kind: "app" };
}
/** Target for the org catalog: `<root>/generated/catalog.ts`. */
export function orgCatalogTarget(root) {
    return { dir: join(root, "generated"), handle: "catalog", name: "Org", kind: "org" };
}
/** The catalog file path for a target. */
export function barrelPathFor(target) {
    return join(target.dir, `${target.filename ?? target.handle}.ts`);
}
/**
 * Write a single flat catalog file for the given refs. This is the canonical
 * write path: one file, factory-based format, no sub-directories.
 *
 * With `preserveIfPulled: true`, skips the write when the file already
 * contains `export default` — indicating a pulled app source lives there and
 * should not be clobbered by a reference-only catalog write.
 */
export async function writeFlatCatalog(target, refs, opts) {
    await mkdir(target.dir, { recursive: true });
    const catalogPath = barrelPathFor(target);
    if (opts?.preserveIfPulled) {
        try {
            const existing = await readFile(catalogPath, "utf8");
            if (existing.includes("export default"))
                return { catalogPath };
        }
        catch { /* file doesn't exist — proceed with write */ }
    }
    const rendered = renderCatalog({ kind: target.kind, refName: target.handle, name: target.name }, refs);
    if (opts?.skipIfUnchanged) {
        try {
            const existing = await readFile(catalogPath, "utf8");
            if (existing === rendered)
                return { catalogPath };
        }
        catch { /* file doesn't exist — proceed with write */ }
    }
    await writeFile(catalogPath, rendered, "utf8");
    return { catalogPath };
}
// ---------------------------------------------------------------------------
// Legacy fragment + barrel writers (kept for import-entity additive path)
// ---------------------------------------------------------------------------
function fragmentImportPath(kind, handle) {
    return `./${bagName(kind)}/${handle}.js`;
}
/** @deprecated Use writeFlatCatalog instead. */
export async function writeFragment(target, ref) {
    const bagDir = join(target.dir, bagName(ref.__kind));
    await mkdir(bagDir, { recursive: true });
    const path = join(bagDir, `${ref.refName}.ts`);
    await writeFile(path, renderFragment(ref), "utf8");
    return { path, importPath: fragmentImportPath(ref.__kind, ref.refName) };
}
/** @deprecated Use writeFlatCatalog instead. */
export async function regenerateBarrel(target) {
    const entries = [];
    for (const meta of CATALOG_META_BY_REF_KIND.values()) {
        const kind = meta.refKind;
        let files;
        try {
            files = await readdir(join(target.dir, meta.catalogBag));
        }
        catch (err) {
            if (err.code === "ENOENT")
                continue;
            throw err;
        }
        for (const file of files) {
            if (!file.endsWith(".ts"))
                continue;
            const refName = file.slice(0, -".ts".length);
            entries.push({ kind, refName, importPath: fragmentImportPath(kind, refName) });
        }
    }
    await mkdir(target.dir, { recursive: true });
    const barrelPath = barrelPathFor(target);
    await writeFile(barrelPath, renderBarrel({ kind: target.kind, refName: target.handle, name: target.name }, entries), "utf8");
    return barrelPath;
}
/** @deprecated Use writeFlatCatalog instead. */
export async function writeCatalog(target, refs) {
    for (const ref of refs)
        await writeFragment(target, ref);
    const barrelPath = await regenerateBarrel(target);
    return { barrelPath };
}
